import type { PhotoId } from './ids'

export type Credit = {
  alt: string
  caption: string
  author: string
  licence: string
  licenceUrl: string
  // The file's page on Wikimedia Commons.
  source: string
  // A painting full of detail, saved larger (1280 to 1600 px) so it can be zoomed into.
  zoom?: boolean
}

const commons = (file: string) => `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(file.replaceAll(' ', '_'))}`
const BY_SA_4 = { licence: 'CC BY-SA 4.0', licenceUrl: 'https://creativecommons.org/licenses/by-sa/4.0/' }
const BY_SA_3_DE = { licence: 'CC BY-SA 3.0 DE', licenceUrl: 'https://creativecommons.org/licenses/by-sa/3.0/de/deed.en' }
const BY_SA_3_NL = { licence: 'CC BY-SA 3.0 NL', licenceUrl: 'https://creativecommons.org/licenses/by-sa/3.0/nl/deed.en' }
const CC0 = { licence: 'CC0 (public domain)', licenceUrl: 'https://creativecommons.org/publicdomain/zero/1.0/' }
const BY_4 = { licence: 'CC BY 4.0', licenceUrl: 'https://creativecommons.org/licenses/by/4.0/' }
const BY_SA_2 = { licence: 'CC BY-SA 2.0', licenceUrl: 'https://creativecommons.org/licenses/by-sa/2.0/' }
const BY_SA_3 = { licence: 'CC BY-SA 3.0', licenceUrl: 'https://creativecommons.org/licenses/by-sa/3.0/' }
const BY_3 = { licence: 'CC BY 3.0', licenceUrl: 'https://creativecommons.org/licenses/by/3.0/' }
const BY_2 = { licence: 'CC BY 2.0', licenceUrl: 'https://creativecommons.org/licenses/by/2.0/' }
const BY_3_NL = { licence: 'CC BY 3.0 NL', licenceUrl: 'https://creativecommons.org/licenses/by/3.0/nl/deed.en' }
const BY_SA_2_5 = { licence: 'CC BY-SA 2.5', licenceUrl: 'https://creativecommons.org/licenses/by-sa/2.5/' }
const BY_2_5 = { licence: 'CC BY 2.5', licenceUrl: 'https://creativecommons.org/licenses/by/2.5/' }
const BY_2_5_NL = { licence: 'CC BY 2.5 NL', licenceUrl: 'https://creativecommons.org/licenses/by/2.5/nl/deed.en' }
const BY_SA_1 = { licence: 'CC BY-SA 1.0', licenceUrl: 'https://creativecommons.org/licenses/by-sa/1.0/' }
// Free to use for any purpose, as long as the author is named.
const ATTRIBUTION = { licence: 'Free with attribution', licenceUrl: 'https://commons.wikimedia.org/wiki/Template:Attribution' }
// Nationaal Archief photos shared on Flickr Commons, with no known copyright restrictions.
const NO_RESTRICTIONS = { licence: 'No known copyright restrictions', licenceUrl: 'https://creativecommons.org/publicdomain/mark/1.0/' }
// Old artworks whose copyright has long expired; Commons marks them public domain.
const PD = { licence: 'Public domain', licenceUrl: 'https://creativecommons.org/publicdomain/mark/1.0/' }

